const Portraits = {
  src(p) { return /^https?:/.test(p) ? p : PHOTO_BASE + p; },
  leader(name) { const v = name && LEADER_PHOTOS[name]; return v ? { src: this.src(v[0]), page: v[1] } : null; },
  event(id) { const v = id && EVENT_PHOTOS[id]; return v ? { src: this.src(v[0]), page: v[1] } : null; },
  // Фото лидера или инициалы, если фото нет / не загрузилось
  html(name, cls = '') {
    const p = this.leader(name);
    const ini = U.esc(Politics.initials(name));
    if (!p) return `<span class="ptr ${cls}">${ini}</span>`;
    return `<span class="ptr has-photo ${cls}" data-tip="${U.esc(name)} · фото: Википедия («${U.esc(p.page)}»)"><img src="${p.src}" alt="" referrerpolicy="no-referrer" onerror="this.parentNode.classList.remove('has-photo');this.remove()"><span>${ini}</span></span>`;
  },
  // Иллюстрация события: фото или null
  eventImg(id, cls = '') {
    const p = this.event(id);
    if (!p) return '';
    return `<img class="${cls}" src="${p.src}" alt="" referrerpolicy="no-referrer" data-tip="Фото: Википедия («${U.esc(p.page)}»)" onerror="this.closest('.has-photo') && this.closest('.has-photo').classList.remove('has-photo');this.remove()">`;
  }
};
